-- Content edits also recheck teaching eligibility/identity after concurrent guardian withdrawal.
--> statement-breakpoint
CREATE TRIGGER course_content_privacy_guard BEFORE UPDATE OF title,subtitle,description,category_id,level,language,price_in_paise,learning_outcomes,requirements,thumbnail_key ON courses WHEN NOT ((EXISTS (SELECT 1 FROM account_privacy a JOIN users u ON u.id=a.user_id WHERE u.id=NEW.instructor_id AND u.status='active' AND u.email_verified_at IS NOT NULL AND a.birth_date<=printf('%04d',CAST(strftime('%Y','now') AS INTEGER)-16) || strftime('-%m-%d','now') AND a.terms_version='2026-10-12' AND a.privacy_version='2026-10-12' AND a.instructor_version='2026-10-12' AND (a.birth_date<=printf('%04d',CAST(strftime('%Y','now') AS INTEGER)-18) || strftime('-%m-%d','now') OR EXISTS (SELECT 1 FROM guardian_requests g JOIN users parent ON parent.id=g.guardian_user_id JOIN account_privacy adult ON adult.user_id=parent.id JOIN guardian_verifications v ON v.request_id=g.id WHERE g.id=a.guardian_request_id AND g.status='approved' AND g.consent_version='2026-10-12' AND g.identity_method='setu_digilocker' AND g.verification_reference IS NOT NULL AND v.verified_at IS NOT NULL AND parent.status='active' AND parent.email_verified_at IS NOT NULL AND adult.birth_date<=printf('%04d',CAST(strftime('%Y','now') AS INTEGER)-18) || strftime('-%m-%d','now') AND adult.terms_version='2026-10-12' AND adult.privacy_version='2026-10-12' AND g.scope='teaching')))) AND EXISTS (SELECT 1 FROM teacher_verifications WHERE user_id=NEW.instructor_id AND verified_at IS NOT NULL AND valid_until>CAST(strftime('%s','now') AS INTEGER)*1000)) BEGIN SELECT RAISE(ABORT,'PRIVACY_ELIGIBILITY'); END;
--> statement-breakpoint
